const body = $('Webhook IA').item.json.body || {};
const userPrompt = body.prompt || 'Resume el estado general del inventario';
const context = body.context || {};

const products = context.products || [];
const movements = context.movements || [];
const alerts = context.alerts || [];

const totalProducts = products.length;
const outOfStock = products.filter(p => Number(p.stock) <= 0);
const lowStock = products.filter(p => Number(p.stock) > 0 && Number(p.stock) <= Number(p.minimumStock));
const totalValue = products.reduce((acc, p) => acc + (Number(p.stock) * Number(p.purchasePrice || 0)), 0);
const criticalAlerts = alerts.filter(a => a.status === 'critical' || a.status === 'active');

// Resumen de salidas recientes
const recentExits = movements.filter(m => m.type === 'EXIT').slice(-10);

const systemContext = `
Eres StockPilot IA, el copiloto logístico e inteligente del sistema de gestión de inventarios StockPilot.

ESTADO ACTUAL DEL INVENTARIO EN TIEMPO REAL:
- Total de referencias SKU registradas: ${totalProducts}
- Valorización total del inventario: $${totalValue.toLocaleString('en-US', { minimumFractionDigits: 2 })} USD
- Artículos agotados (${outOfStock.length}): ${outOfStock.map(p => `${p.name} (SKU: ${p.sku})`).join(', ') || 'Ninguno'}
- Artículos en stock bajo/mínimo (${lowStock.length}): ${lowStock.map(p => `${p.name} (Stock: ${p.stock}, Mín: ${p.minimumStock})`).join(', ') || 'Ninguno'}
- Alertas críticas activas: ${criticalAlerts.length}
- Movimientos recientes registrados: ${movements.length} transacciones (${recentExits.length} salidas analizadas)

DIRECTRICES DE RESPUESTA:
1. Responde de forma profesional, clara, ejecutiva y estructurada con viñetas markdown y emojis relevantes.
2. Si el usuario pregunta por compras o reabastecimiento, prioriza los artículos agotados y con stock bajo indicando sus SKUs.
3. Si pregunta por rotación, analiza los datos y sugiere acciones comerciales o de reubicación.
4. Si pregunta por clasificación, recomienda las familias taxonómicas estándar de StockPilot (TEC, FER, ALI, FAR, OFI, TEX, AUT, GEN).
5. Mantén un tono amigable, predictivo y orientado a la toma de decisiones empresariales.`;

return {
  systemContext,
  userPrompt,
  chatInput: `Contexto del inventario:\n${systemContext}\n\nConsulta del usuario:\n"${userPrompt}"`,
  metrics: {
    totalProducts,
    outOfStockCount: outOfStock.length,
    lowStockCount: lowStock.length,
    totalValue,
    criticalAlertsCount: criticalAlerts.length
  }
};

const agentOutput = $json.output || $json.text || $json.response || 'Análisis logístico completado con éxito.';

return {
  success: true,
  source: 'n8n_gemini_agent',
  response: agentOutput,
  timestamp: new Date().toISOString()
};
